            writer.WriteNumber("citation_rate_denominator", citationGroupRow.CitationRateDenominator);

            writer.WritePropertyName("models");
            JsonSerializer.Serialize(writer, citationGroupRow.Models, jsonSerializerOptions);
            if (citationGroupRow.AvgCitationPosition != null)
                writer.WriteNumber("avg_citation_position", citationGroupRow.AvgCitationPosition.Value);
            else
                writer.WriteNull("avg_citation_position");

            if (citationGroupRow.FirstSeenAt != null)
                writer.WriteString("first_seen_at", citationGroupRow.FirstSeenAt.Value.ToString(FirstSeenAtFormat));
            else
                writer.WriteNull("first_seen_at");

            if (citationGroupRow.LastSeenAt != null)
                writer.WriteString("last_seen_at", citationGroupRow.LastSeenAt.Value.ToString(LastSeenAtFormat));
            else
                writer.WriteNull("last_seen_at");

            if (citationGroupRow.UrlOption.IsSet)
                writer.WriteString("url", citationGroupRow.Url);

            if (citationGroupRow.UrlSha256Option.IsSet)
                if (citationGroupRow.UrlSha256Option.Value != null)
                    writer.WriteString("url_sha256", citationGroupRow.UrlSha256);
                else
                    writer.WriteNull("url_sha256");

            if (citationGroupRow.NormalizedUrlOption.IsSet)
                if (citationGroupRow.NormalizedUrlOption.Value != null)
                    writer.WriteString("normalized_url", citationGroupRow.NormalizedUrl);
                else
                    writer.WriteNull("normalized_url");

            if (citationGroupRow.PageCacheOption.IsSet)
            {
                writer.WritePropertyName("page_cache");
                JsonSerializer.Serialize(writer, citationGroupRow.PageCache, jsonSerializerOptions);
            }
            if (citationGroupRow.PageMentionsOption.IsSet)
            {
                writer.WritePropertyName("page_mentions");
                JsonSerializer.Serialize(writer, citationGroupRow.PageMentions, jsonSerializerOptions);
            }
            if (citationGroupRow.DomainOption.IsSet)
                writer.WriteString("domain", citationGroupRow.Domain);

            if (citationGroupRow.HostOption.IsSet)
                writer.WriteString("host", citationGroupRow.Host);

            if (citationGroupRow.AggregateDetailsOption.IsSet)
            {
                writer.WritePropertyName("aggregate_details");
                JsonSerializer.Serialize(writer, citationGroupRow.AggregateDetails, jsonSerializerOptions);
            }
            if (citationGroupRow.CitationSeriesOption.IsSet)
            {
                writer.WritePropertyName("citation_series");
                JsonSerializer.Serialize(writer, citationGroupRow.CitationSeries, jsonSerializerOptions);
            }
        }
    }
